function checkAges(texts) {
  const good = [];
  let bad = 0;
  for (const text of texts) {
    try {
      const n = JSON.parse(text);
      if (typeof n !== "number" || n < 0 || n > 120) {
        throw new Error("bad age");
      }
      good.push(n);
    } catch (error) {
      bad++;
    }
  }
  return [good, bad];
}
